// api/aiApi.js
import axiosInstance from './axiosInstance';

// AI 광고 효율 예측
export const predictAdEfficiency = async (data) => {
  const response = await axiosInstance.post('/ai/predict', data);
  return response.data;
};

// AI 콘텐츠 개선 제안
export const getContentSuggestions = async (data) => {
  const response = await axiosInstance.post('/ai/suggest', data);
  return response.data;
};
